import Navbar from "@/components/shared/Navbar";
import Footer from "@/components/shared/Footer";
import BlogDetailClient from "./BlogDetailClient";
import type { Metadata, ResolvingMetadata } from "next";

// This is required for Next.js static export


export async function generateMetadata(
  { params }: { params: Promise<{ slug: string }> },
  parent: ResolvingMetadata
): Promise<Metadata> {
  const resolvedParams = await params;
  const slug = resolvedParams.slug;
  const apiBase = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";
  
  try {
    const res = await fetch(`${apiBase}/api/blogs/${slug}`, { cache: "no-store" });
    if (res.ok) {
      const json = await res.json();
      if (json.success && json.data) {
        const post = json.data;
        return {
          title: `${post.seoTitle || post.title} | House Of Wasila`,
          description: post.seoDescription || post.excerpt,
          openGraph: {
            title: post.seoTitle || post.title,
            description: post.seoDescription || post.excerpt,
            type: "article",
            images: post.featuredImage ? [post.featuredImage] : [],
          }
        };
      }
    }
  } catch (e) {
    // Fallback to default
  }

  return {
    title: "Article | House Of Wasila",
    description: "Read our latest insights and stories.",
  };
}

export default async function BlogDetailPage({ params }: { params: Promise<{ slug: string }> }) {
  const resolvedParams = await params;
  return (
    <>
      <Navbar />
      <main className="relative flex flex-col w-full">
        <BlogDetailClient slug={resolvedParams.slug} />
      </main>
      <Footer />
    </>
  );
}
